#include <iostream>
#include <algorithm>
#include <numeric>
using namespace std;

long long gcdLL(long long a, long long b) {
    while (b != 0) {
        long long temp = a % b;
        a = b;
        b = temp;
    }
    return a;
}

struct Fraction {
    long long numerator;
    long long denominator;

    Fraction() : numerator(0), denominator(1) {}
    Fraction(long long n, long long d) : numerator(n), denominator(d) {}

    void reduce() {
        long long g = gcdLL(numerator, denominator);
        numerator /= g;
        denominator /= g;
    }

    bool operator<(const Fraction& other) const {
        return numerator * other.denominator < other.numerator * denominator;
    }

    void print() const {
        cout << numerator << "/" << denominator;
    }
};

int main() {
    long long x, y, n;
    cin >> x >> y >> n;
    Fraction limit(50, 1);
    Fraction base(x, y);
    Fraction minFraction;
    long long minR = 0, minI = 1;

    for (long long i = 1; i <= n; ++i) {
        long long r = (base.numerator * i) / base.denominator;
        long long z = (base.numerator * i) % base.denominator;
        if (z > base.denominator / 2) {
            r++;
            z = base.denominator - z;
        }
        Fraction current(z, i * base.denominator);
        if (current < limit) {
            limit = current;
            minR = r;
            minI = i;
        }
    }
    cout << minR;
}
